    /**
     * Method to retrieve the Enterprise via an FindEnterpriseQuery
     * @return 	query	FindEnterpriseQuery
     */
    @SuppressWarnings("unused")
    public Enterprise find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Enterprise - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
